function smallestRepunitDivByK(k) {
  // Follow the remainders until one repeats; a repeat without hitting 0 means never.
  const seen = new Set();
  let value = 1 % k;
  let digits = 1;
  while (!seen.has(value)) {
    if (value === 0) return digits;
    seen.add(value);
    value = (value * 10 + 1) % k;
    digits++;
  }
  return -1;
}

